4	
5	/**
6	 * The Luhn check digit (0-9) computed over the decimal digits contained in an owner's
7	 * {@code customerCode}. Non-digit characters (letters, separators) are ignored, so the digit is
8	 * derived purely from the numeric portion of the code (e.g. the {@code 0007} sequence in
9	 * {@code LON-SMI-0007}).
10	 */
11	public final class CustomerCodeCheckDigit {
12	
13	    private CustomerCodeCheckDigit() {
14	    }
15	
16	    /** The check digit of an already-assigned owner's customer code. */
17	    public static Integer of(Owner owner) {
18	        String customerCode = owner.getCustomerCode();
19	        return customerCode == null ? null : luhn(customerCode);
20	    }
21	
22	    /** Luhn check digit (0-9) over the decimal digits contained in {@code value}. */
23	    static int luhn(String value) {
24	        int sum = 0;
25	        boolean dbl = true;
26	        for (int i = value.length() - 1; i >= 0; i--) {
27	            char c = value.charAt(i);
28	            if (c < '0' || c > '9') {
29	                continue;
30	            }
31	            int d = c - '0';
32	            if (dbl) {
33	                d *= 2;
34	                if (d > 9) {
35	                    d -= 9;
36	                }
37	            }
38	            sum += d;
39	            dbl = !dbl;
40	        }
41	        return (10 - (sum % 10)) % 10;
42	    }
43	}
