7	/**
8	 * Fixed region-to-postcode-range table used to validate an owner's postcode against its city.
9	 * The city's region is derived by {@link LocalityLookup#regionOf(String)}; a region absent from
10	 * this table (including the 'UNKNOWN' default for unmapped cities) accepts any 4-digit postcode.
11	 */
12	public final class PostcodeRegions {
13	
14	    /** Region -> inclusive 4-digit postcode range {low, high}. */
15	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
16	            "NSW", new int[] {2000, 2099},
17	            "VIC", new int[] {3000, 3099},
18	            "QLD", new int[] {4000, 4099});
19	
20	    private PostcodeRegions() {
21	    }
22	
23	    /**
24	     * Whether {@code postcode} (already known to be four digits) is acceptable for {@code city}.
25	     * Cities whose region has no pinned range accept any 4-digit postcode.
26	     */
27	    public static boolean isValidFor(String city, String postcode) {
28	        int[] range = REGION_POSTCODES.get(LocalityLookup.regionOf(city));
29	        if (range == null) {
30	            return true;
31	        }
32	        int value = Integer.parseInt(postcode);
33	        return value >= range[0] && value <= range[1];
34	    }
