1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * The single derived key that all owner duplicate detection is expressed through:
13	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners are
14	 * duplicates only when their whole {@code identityKey} is equal. Because the normalized telephone is
15	 * part of the key, two members of the same household (same {@code householdId}) with different
16	 * telephones have different keys and are both allowed; only an exact full-key match is a duplicate.
17	 *
18	 * <ul>
19	 * <li><b>normalizedTelephone</b> — the E.164 form (see {@link E164Telephone}); the stored telephone
20	 * is already E.164 and re-normalizing is idempotent.</li>
21	 * <li><b>email</b> — the lower-cased address, or empty when the owner has none.</li>
22	 * <li><b>householdId</b> — the owner's assigned shared-household id (see {@link AssignHousehold}), or
23	 * empty when the owner is not part of a shared household.</li>
24	 * </ul>
25	 */
26	public final class OwnerIdentityKey {
27	
28	    private OwnerIdentityKey() {
29	    }
30	
31	    /** The identity key of an already-built/stored owner. */
32	    public static String of(Owner owner) {
33	        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
34	    }
35	
36	    /** The identity key from raw parts. Null telephone or email contribute an empty segment. */
37	    static String build(String telephone, String email, String householdId) {
38	        String tel = E164Telephone.toE164OrNull(telephone);
39	        return (tel == null ? "" : tel) + "|"
40	                + (email == null ? "" : email.trim().toLowerCase()) + "|"
41	                + (householdId == null ? "" : householdId);
42	    }
43	
44	    /**
45	     * The household id a create request would be assigned, mirroring {@link AssignHousehold}: only a
46	     * request opting into a shared household ({@code sharesHousehold} true) that matches an existing
47	     * owner's normalized last name and address gets one; otherwise it has none (empty segment).
48	     */
49	    static String prospectiveHouseholdId(OwnerFieldsDto request, OwnerRepository ownerRepository) {
50	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
51	            return null;
52	        }
53	        String lastName = normalizeName(request.getLastName());
54	        String address = AddressNormalizer.normalize(request.getAddress());
55	        for (Owner existing : ownerRepository.findAll()) {
56	            if (normalizeName(existing.getLastName()).equals(lastName)
57	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
58	                return householdId(lastName, address);
59	            }
60	        }
61	        return null;
62	    }
63	
64	    /** Last-name / address normalization used for household grouping: trim, collapse whitespace, lower-case. */
65	    static String normalizeName(String value) {
66	        if (value == null) {
67	            return "";
68	        }
69	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
70	    }
71	
72	    /** Stable household id: upper-case hex of the first 8 bytes of SHA-256 of the normalized parts. */
73	    static String householdId(String normalizedLastName, String normalizedAddress) {
74	        try {
75	            byte[] digest = MessageDigest.getInstance("SHA-256")
76	                    .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
77	            StringBuilder sb = new StringBuilder(16);
78	            for (int i = 0; i < 8; i++) {
79	                sb.append(String.format("%02x", digest[i]));
80	            }
81	            return sb.toString().toUpperCase();
82	        }
83	        catch (NoSuchAlgorithmException e) {
84	            throw new IllegalStateException("SHA-256 unavailable", e);
85	        }
86	    }
87	}
