4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns, on the owner being created, the numeric membership level. The level starts at one, gains a
8	 * point when an email is present and a further point when the owner has no pre-existing namesakes
9	 * ({@code namesakeCount} of zero), and is capped at three. Level four is reserved for tenure and is
10	 * never assigned at creation. Runs after {@link NormalizeOwnerEmail} and {@link AssignNamesakeCount}
11	 * so both inputs are settled, and before {@link SaveOwner} persists the value.
12	 */
13	public class AssignMembershipLevel {
14	
15	    public void service(@Val Owner owner) {
16	        int level = 1;
17	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
18	            level++;
19	        }
20	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
21	            level++;
22	        }
23	        owner.setMembershipLevel(Math.min(level, 3));
24	    }
25	}
