package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.LocalityLookup;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
 * region derived from the owner's postcode (see {@link LocalityLookup#regionOf(String, String)}) and
 * HASH8 is the first eight upper-case hex characters of SHA-256 over the concatenation of the owner's
 * normalized (E.164) telephone and last name (e.g. {@code NSW-1A2B3C4D}). There is no sequence number,
 * so the code is stable for a given telephone/last-name/region and does not depend on how many owners
 * already exist. Every value built from the customerCode — the membership number, its check digit, the
 * create audit line and the derived locality — follows this region-and-hash identity.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        owner.setCustomerCode(regionOf(owner) + "-" + hash8(owner));
    }

    /**
     * The REGION segment of the owner's identity: the prefix of an already-assigned
     * {@code customerCode}, otherwise the region derived from the owner's postcode (city as fallback).
     * Deriving locality from this is how the read-time locality moves onto the identity.
     */
    public static String regionOf(Owner owner) {
        String code = owner.getCustomerCode();
        if (code != null) {
            int dash = code.indexOf('-');
            if (dash > 0) {
                return code.substring(0, dash);
            }
        }
        return LocalityLookup.regionOf(owner.getCity(), owner.getPostcode());
    }

    /** First eight upper-case hex characters of SHA-256(normalizedTelephone + lastName). */
    private static String hash8(Owner owner) {
        // The stored telephone is already E.164 (see NormalizeOwnerTelephone); re-normalizing is
        // idempotent and falls back to the stored value if it somehow cannot be parsed.
        String normalizedTelephone = E164Telephone.toE164OrNull(owner.getTelephone());
        if (normalizedTelephone == null) {
            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        }
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((normalizedTelephone + lastName).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
